package com.wjx871.population.keypopulation;import com.wjx871.population.application.*;import com.wjx871.population.common.BusinessException;import com.wjx871.population.material.ApplicationMaterialMapper;import com.wjx871.population.security.DataScopeCriteria;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;
import com.wjx871.population.security.CurrentUserContext;
@Component@RequiredArgsConstructor class KeyPopulationWorkflow implements ApplicationSubmissionValidator,ApplicationStatusListener{private final KeyPopulationMapper mapper;private final KeyPopulationReleasePolicy releasePolicy;private final ApplicationMaterialMapper materials;
public boolean supports(BusinessType t){return t==BusinessType.KEY_POPULATION_REGISTER||t==BusinessType.KEY_POPULATION_RELEASE;}public void validate(BusinessApplication a){requireSubmitPermissions();KeyPopulationApplication d=mapper.findApplication(a.getApplicationId()).orElseThrow(()->bad("重点人口申请详情不存在"));if(a.getBusinessType()==BusinessType.KEY_POPULATION_RELEASE){releasePolicy.validateSubmission(a,d);}else{if(d.getOperationType()!=KeyOperationType.REGISTER||!Objects.equals(a.getTargetPersonId(),d.getPersonId()))throw new BusinessException(HttpStatus.FORBIDDEN,"建档申请关联不一致");String status=mapper.personScopedStatus(d.getPersonId(),DataScopeCriteria.current()).orElseThrow(()->new BusinessException(HttpStatus.FORBIDDEN,"超出人员数据范围"));if("CANCELLED".equals(status)||"DECEASED".equals(status))throw conflict("已注销或死亡人员不能建档");}Set<String> types=new HashSet<>();materials.selectByApplicationId(a.getApplicationId()).stream().filter(x->Boolean.TRUE.equals(x.getRequiredFlag())).forEach(x->types.add(x.getMaterialType()));if(!types.contains("KEY_POPULATION_BASIS")||!types.contains("SITUATION_DESCRIPTION"))throw conflict("缺少重点人口登记依据或情况说明材料");}
private void requireSubmitPermissions() {
    // Enforce both permissions for HTTP and direct ApprovalService submissions before any writes.
    List<String> permissions = CurrentUserContext.requireUser().permissions();
    if (!permissions.contains("application:submit") || !permissions.contains("key-population:apply")) {
        throw new BusinessException(HttpStatus.FORBIDDEN, "提交重点人口申请需要申请权限和提交权限");
    }
}
public void onStatusChanged(BusinessApplication a,ApplicationStatus s){KeyPopulationApplication d=mapper.findApplication(a.getApplicationId()).orElse(null);if(d==null)return;KeyApplicationStatus to=switch(s){case UNDER_REVIEW,SUBMITTED->KeyApplicationStatus.UNDER_REVIEW;case APPROVED->KeyApplicationStatus.APPROVED;case REJECTED->KeyApplicationStatus.REJECTED;case WITHDRAWN,CANCELLED->KeyApplicationStatus.WITHDRAWN;default->null;};if(to!=null&&mapper.updateApplicationStatus(a.getApplicationId(),d.getBusinessStatus(),to,d.getVersion())==0)ApplicationService.conflict();}private BusinessException bad(String m){return new BusinessException(HttpStatus.BAD_REQUEST,m);}private BusinessException conflict(String m){return new BusinessException(HttpStatus.CONFLICT,m);}}
